// @FIGURE_CODE_BEGIN
(function () {
  var W = 1000, H = 347;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H).attr('preserveAspectRatio', 'xMidYMid meet');

  var gScene = draw.group(), gLive = draw.group(), gPanel = draw.group(),
      gHi = draw.group(), gLabel = draw.group();

  // ---------- scene constants ----------
  var GROUND_Y = 333;
  var CAM = { x0: 60, x1: 186, y0: 141, y1: 300 };
  var APX = CAM.x1, APY = 220;
  var DOT_HI = { x: 71, y: 159 }, DOT_LO = { x: 71, y: 246 };
  var FREE_A = { x: 380, y: 240 }, FREE_B = { x: 466, y: 90 };

  var TYPES = {
    sky:    { c: '#b6c4d2', i: 0.88, n: 'sky (bright, low-detail)' },
    tree:   { c: '#28c80f', i: 0.72, n: 'tree canopy (green)' },
    trunk:  { c: '#8a5a2e', i: 0.46, n: 'tree trunk (brown)' },
    ground: { c: '#111111', i: 0.18, n: 'ground (dark)' },
    bird:   { c: '#333333', i: 0.32, n: 'bird' },
    camera: { c: '#555555', i: 0.20, n: 'camera body' },
    zero:   { c: '#ccd2d8', i: 0.0,  n: 'zero — blocked by camera wall' }
  };

  var CANOPY = [[700,118,40],[716,86,36],[752,76,36],[796,78,36],[828,96,32],[836,124,30],
                [810,146,28],[772,152,26],[730,146,30],[690,130,32],[668,110,26],
                [756,110,52],[800,116,44],[716,116,40]];
  var TRUNK = [[716,150],[744,142],[762,132],[778,142],[784,168],[776,220],[780,270],
               [786,306],[790,330],[762,330],[758,320],[726,320],[722,330],[696,330],
               [694,300],[702,250],[708,200],[710,170]];

  var state = { inside: false, aperture: 3, px: FREE_A.x, py: FREE_A.y };
  var hoverTheta = 0.4;

  // ---------- helpers ----------
  function label(g, str, x, y, size, anchor, color) {
    var t = g.text(str);
    t.font({ family: 'sans-serif', size: size, anchor: anchor || 'start' });
    t.fill(color || '#000');
