// @FIGURE_CODE_BEGIN
(function () {
  var W = 1000, H = 347;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H).attr('preserveAspectRatio', 'xMidYMid meet');

  var gScene = draw.group(), gLive = draw.group(), gPanel = draw.group(),
      gHi = draw.group(), gLabel = draw.group();

  // ---------- scene constants ----------
  var GROUND_Y = 333;
  var CAM = { x0: 60, x1: 186, y0: 141, y1: 300 };
  var APX = CAM.x1, APY = 220;
  var DOT_HI = { x: 71, y: 159 }, DOT_LO = { x: 71, y: 246 };
  var FREE_A = { x: 380, y: 240 }, FREE_B = { x: 466, y: 90 };

  var TYPES = {
    sky:    { c: '#b6c4d2', i: 0.88, n: 'sky (bright, low-detail)' },
    tree:   { c: '#28c80f', i: 0.72, n: 'tree canopy (green)' },
    trunk:  { c: '#8a5a2e', i: 0.46, n: 'tree trunk (brown)' },
    ground: { c: '#111111', i: 0.18, n: 'ground (dark)' },
    bird:   { c: '#333333', i: 0.32, n: 'bird' },
    camera: { c: '#555555', i: 0.20, n: 'camera body' },
    zero:   { c: '#ccd2d8', i: 0.0,  n: 'zero — blocked by camera wall' }
  };

  var CANOPY = [[700,118,40],[716,86,36],[752,76,36],[796,78,36],[828,96,32],[836,124,30],
                [810,146,28],[772,152,26],[730,146,30],[690,130,32],[668,110,26],
                [756,110,52],[800,116,44],[716,116,40]];
  var TRUNK = [[716,150],[744,142],[762,132],[778,142],[784,168],[776,220],[780,270],
               [786,306],[790,330],[762,330],[758,320],[726,320],[722,330],[696,330],
               [694,300],[702,250],[708,200],[710,170]];

  var state = { inside: false, aperture: 3, px: FREE_A.x, py: FREE_A.y };
  var hoverTheta = 0.4;

  // ---------- helpers ----------
  function label(g, str, x, y, size, anchor, color) {
    var t = g.text(str);
    t.font({ family: 'sans-serif', size: size, anchor: anchor || 'start' });
    t.fill(color || '#000');
    t.attr('x', x).attr('y', y);
    var ts = t.node.querySelector('tspan');
    if (ts) { ts.setAttribute('x', x); ts.setAttribute('y', y); ts.setAttribute('dy', 0); }
    return t;
  }
  function halo(t) {
    t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
    return t;
  }
  function drawArrow(g, x1, y1, x2, y2, color, w, hs) {
    var ang = Math.atan2(y2 - y1, x2 - x1);
    var bx = x2 - Math.cos(ang) * hs, by = y2 - Math.sin(ang) * hs;
    var ln = g.line(x1, y1, bx, by).stroke({ color: color, width: w, linecap: 'round' });
    var nx = Math.cos(ang + Math.PI / 2) * hs * 0.36, ny = Math.sin(ang + Math.PI / 2) * hs * 0.36;
    g.polygon([[x2, y2], [bx + nx, by + ny], [bx - nx, by - ny]]).fill(color).stroke('none');
    return ln;
  }
  function hitLine(g, x1, y1, x2, y2, tip) {
    var h = g.line(x1, y1, x2, y2).stroke({ color: '#000', width: 7, opacity: 0 }).css('cursor', 'pointer');
    h.on('mousemove', function (e) { showTooltip(tip, e); });
    h.on('mouseleave', hideTooltip);
    return h;
  }
  function clamp(v, a, b) { return Math.min(b, Math.max(a, v)); }

  // ---------- geometry tests ----------
  function inCanopy(x, y) {
    if (x < 638 || x > 872 || y < 36 || y > 182) return false;
    for (var i = 0; i < CANOPY.length; i++) {
      var c = CANOPY[i], dx = x - c[0], dy = y - c[1];
      if (dx * dx + dy * dy <= c[2] * c[2]) return true;
    }
    return false;
  }
  function inTrunk(x, y) {
    if (x < 690 || x > 792 || y < 128 || y > 332) return false;
    var inside = false;
    for (var i = 0, j = TRUNK.length - 1; i < TRUNK.length; j = i++) {
      var xi = TRUNK[i][0], yi = TRUNK[i][1], xj = TRUNK[j][0], yj = TRUNK[j][1];
      if (((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi)) inside = !inside;
    }
    return inside;
  }
  function inBird(x, y) { var dx = x - 952, dy = y - 30; return dx * dx + dy * dy < 270; }
  function apGap() { return Math.max(0.6, state.aperture); }
  function inWall(x, y) {
    if (x < 55 || x > 191 || y < 136 || y > 305) return false;
    if (x >= 57 && x <= 63 && y >= 138 && y <= 303) return true;
    if (y >= 138 && y <= 144 && x >= 57 && x <= 189) return true;
    if (y >= 297 && y <= 303 && x >= 57 && x <= 189) return true;
    if (x >= 183 && x <= 189 && y >= 138 && y <= 303) {
      var a = apGap();
      if (y > APY - a / 2 && y < APY + a / 2) return false;
      return true;
    }
    return false;
  }

  // ---------- ray tracing of the plenoptic function ----------
  function trace(px, py, th, inside) {
    var dx = Math.cos(th), dy = -Math.sin(th), step = 1.8;
    for (var t = 3; t < 1500; t += step) {
      var x = px + dx * t, y = py + dy * t;
      if (inWall(x, y)) return inside ? 'zero' : 'camera';
      if (y >= GROUND_Y) return 'ground';
      if (inCanopy(x, y)) return 'tree';
      if (inTrunk(x, y)) return 'trunk';
      if (inBird(x, y)) return 'bird';
      if (x < -20 || x > W + 20 || y < -20) return 'sky';
    }
    return 'sky';
  }
  function directionList(px, py, inside, count) {
    var d = [], i;
    for (i = 0; i < count; i++) d.push(i * 2 * Math.PI / count);
    if (inside) {
      var a = apGap();
      for (i = 0; i <= 10; i++) {
        var ty = APY - a / 2 + a * i / 10;
        d.push(Math.atan2(-(ty - py), APX + 4 - px));
      }
    }
    d.sort(function (m, n) { return m - n; });
    return d;
  }
  function deg(th) { var v = th * 180 / Math.PI; while (v < 0) v += 360; while (v >= 360) v -= 360; return v; }

  // ---------- static scene ----------
  function drawScene() {
    // ground
    gScene.rect(W, 13).move(0, GROUND_Y).fill('#000');
    // tree
    var canopy = gScene.group();
    CANOPY.forEach(function (c) { canopy.circle(c[2] * 2).center(c[0], c[1]).fill('#28c80f'); });
    var trunk = gScene.polygon(TRUNK).fill('#8a5a2e').stroke('none');
    [canopy, trunk].forEach(function (el) {
      el.css('cursor', 'pointer');
      el.on('mousemove', function (e) { showTooltip('Scene object: emits radiance in every direction', e); });
      el.on('mouseleave', hideTooltip);
      el.on('click', function () {
        showPopup('Scene radiance',
          'Every surface in the scene sends light out in many directions. The plenoptic function L(x,y,θ) records, at each point of empty space, how much of that light arrives from each direction θ — green from the canopy, brown from the trunk, near-black from the ground, bright from the sky.');
      });
    });
    // bird
    gScene.path('M944,52 L946,34 L934,24 L948,26 L952,10 L960,20 L972,16 L964,26 L974,30 L958,32 L952,46 Z')
      .fill('#fff').stroke({ color: '#000', width: 1.5, linejoin: 'round' });
    // camera box (three fixed walls; the right wall is redrawn with the aperture gap)
    var s = { color: '#000', width: 2.2, linecap: 'square' };
    gScene.line(CAM.x0, CAM.y0, CAM.x0, CAM.y1).stroke(s);
    gScene.line(CAM.x0, CAM.y0, CAM.x1, CAM.y0).stroke(s);
    gScene.line(CAM.x0, CAM.y1, CAM.x1, CAM.y1).stroke(s);
    halo(label(gScene, 'Pinhole camera', 50, 130, 18, 'start', '#000'));
    // interior image-plane points
    [DOT_HI, DOT_LO].forEach(function (d) { gScene.circle(14).center(d.x, d.y).fill('#ff0000'); });
    // the two crossing scene rays through the pinhole (image inversion)
    drawArrow(gScene, 262, 260, DOT_HI.x + 6, DOT_HI.y + 3, '#000', 1.2, 7);
    drawArrow(gScene, 262, 203, DOT_LO.x + 6, DOT_LO.y - 3, '#000', 1.2, 7);
    hitLine(gScene, 262, 260, DOT_HI.x, DOT_HI.y, 'Light from below the axis lands above it — the image is inverted');
    hitLine(gScene, 262, 203, DOT_LO.x, DOT_LO.y, 'Light from above the axis lands below it — the image is inverted');
    // static free-space starburst (second sample point, as in the original figure)
    var sb = gScene.group();
    for (var i = 0; i < 20; i++) {
      var th = i * Math.PI / 10;
      var ux = Math.cos(th), uy = -Math.sin(th);
      drawArrow(sb, FREE_B.x + ux * 90, FREE_B.y + uy * 90, FREE_B.x + ux * 18, FREE_B.y + uy * 18, '#000', 1.1, 6);
    }
    gScene.circle(14).center(FREE_B.x, FREE_B.y).fill('#ff0000').css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('A second free-space sample: rays arrive from all 360°', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('A point in free space',
          'At any point of empty space, light is arriving from every direction at once. The starburst of inward arrows is a sample of L(x,y,θ) at this (x,y): one intensity per direction θ. Nothing about a camera is involved.');
      });
  }

  // ---------- dynamic layer ----------
  function drawLive() {
    gLive.clear();
    var s = { color: '#000', width: 2.2, linecap: 'square' };
    var g = Math.max(apGap(), 2.5);
    gLive.line(CAM.x1, CAM.y0, CAM.x1, APY - g / 2).stroke(s);
    gLive.line(CAM.x1, APY + g / 2, CAM.x1, CAM.y1).stroke(s);
    var ap = gLive.rect(6, Math.max(g, 2.5)).center(CAM.x1, APY).fill('#ffffff')
      .stroke({ color: '#d08a00', width: 0.8 }).css('cursor', 'pointer');
    ap.on('mousemove', function (e) { showTooltip('Pinhole: diameter ' + state.aperture.toFixed(1) + ' units', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The aperture does the blocking',
          'The pinhole is the only opening. It admits a narrow cone of directions at each interior point, so L(x,y,θ) inside the camera is zero for almost every θ. Widening it admits more directions — and blurs the image.');
      });

    // live angular sample at the active point
    var dirs = directionList(state.px, state.py, state.inside, 24);
    var i, th, ux, uy, ty, T;
    for (i = 0; i < dirs.length; i++) {
      th = dirs[i]; ux = Math.cos(th); uy = -Math.sin(th);
      ty = trace(state.px, state.py, th, state.inside);
      T = TYPES[ty];
      if (ty === 'zero') {
        gLive.line(state.px + ux * 30, state.py + uy * 30, state.px + ux * 46, state.py + uy * 46)
          .stroke({ color: T.c, width: 0.9, linecap: 'round' }).attr('stroke-dasharray', '2,2.5');
      } else {
        drawArrow(gLive, state.px + ux * 90, state.py + uy * 90, state.px + ux * 18, state.py + uy * 18,
          T.c, 1.2, 6);
        hitLine(gLive, state.px + ux * 90, state.py + uy * 90, state.px + ux * 20, state.py + uy * 20,
          'θ = ' + deg(th).toFixed(0) + '°  →  ' + T.n);
      }
    }

    // active marker
    gLive.circle(26).center(state.px, state.py).fill('none').stroke({ color: '#ff9a9a', width: 2.5 });
    var m = gLive.circle(15).center(state.px, state.py).fill('#ff0000').css('cursor', 'grab');
    m.on('mousemove', function (e) { showTooltip('Drag me — the sample point of L(x, y, θ)', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The active sample point',
          'This marker is the (x, y) at which the plenoptic function is being evaluated. The readout panel shows L as a function of direction θ around it. Drag it into the camera, or out into the open scene, and watch the angular distribution change.');
      });

    if (state.inside) {
      var ct = halo(label(gLive, 'most directions are zero inside the camera', 112, 322, 8.5, 'middle', '#333'));
      gLive.line(112, 314, state.px + 8, state.py + 14).stroke({ color: '#888', width: 0.7 }).attr('stroke-dasharray', '2,2');
      ct.front();
    }
  }

  // ---------- polar readout ----------
  var PX0 = 200, PY0 = 6, PW = 168, PH = 158, CX = 284, CY = 86, PR = 52;
  function drawPanel() {
    gPanel.clear();
    gPanel.rect(PW, PH).move(PX0, PY0).fill('#ffffff').stroke({ color: '#c8ced6', width: 0.8 }).radius(4);
    label(gPanel, 'Angular distribution  L(θ)', CX, PY0 + 13, 8, 'middle', '#333');
    gPanel.circle(PR * 2).center(CX, CY).fill('none').stroke({ color: '#e2e6ea', width: 0.8 }).attr('stroke-dasharray', '2,3');
    gPanel.circle(PR * 0.55 * 2).center(CX, CY).fill('none').stroke({ color: '#eef1f4', width: 0.7 });

    var dirs = directionList(state.px, state.py, state.inside, 132);
    var solids = [];
    for (var i = 0; i < dirs.length; i++) {
      var th = dirs[i], ux = Math.cos(th), uy = -Math.sin(th);
      var ty = trace(state.px, state.py, th, state.inside), T = TYPES[ty];
      if (ty === 'zero') {
        gPanel.line(CX + ux * 7, CY + uy * 7, CX + ux * (7 + PR * 0.22), CY + uy * (7 + PR * 0.22))
          .stroke({ color: T.c, width: 0.7 }).attr('stroke-dasharray', '1.5,2');
      } else {
        solids.push([ux, uy, T]);
      }
    }
    solids.forEach(function (s) {
      var L = 7 + (PR - 7) * s[2].i;
      gPanel.line(CX + s[0] * 7, CY + s[1] * 7, CX + s[0] * L, CY + s[1] * L)
        .stroke({ color: s[2].c, width: 1.5, linecap: 'round' });
    });
    gPanel.circle(5).center(CX, CY).fill('#ff0000');
    label(gPanel, '0°', CX + PR + 6, CY + 3, 6, 'start', '#99a0a8');
    label(gPanel, '90°', CX, CY - PR - 4, 6, 'middle', '#99a0a8');
    label(gPanel, state.inside ? 'point inside the pinhole camera' : 'point in free space',
      CX, CY + PR + 14, 7, 'middle', '#555');
    gPanel.line(PX0 + 9, PY0 + 134, PX0 + 22, PY0 + 134).stroke({ color: '#28c80f', width: 1.6 });
    label(gPanel, 'non-zero radiance', PX0 + 26, PY0 + 136.5, 6.5, 'start', '#555');
    gPanel.line(PX0 + 9, PY0 + 145, PX0 + 22, PY0 + 145).stroke({ color: '#ccd2d8', width: 1.2 }).attr('stroke-dasharray', '1.5,2');
    label(gPanel, 'zero (blocked)', PX0 + 26, PY0 + 147.5, 6.5, 'start', '#555');
  }

  // ---------- probe direction + live L label ----------
  function drawProbe() {
    gHi.clear(); gLabel.clear();
    var th = hoverTheta, ux = Math.cos(th), uy = -Math.sin(th);
    var ty = trace(state.px, state.py, th, state.inside), T = TYPES[ty];
    gHi.line(CX + ux * 6, CY + uy * 6, CX + ux * (PR + 4), CY + uy * (PR + 4))
      .stroke({ color: '#e02020', width: 1.2 }).attr('stroke-dasharray', '3,2');
    gHi.line(state.px + ux * 12, state.py + uy * 12, state.px + ux * 96, state.py + uy * 96)
      .stroke({ color: '#e02020', width: 1, opacity: 0.85 }).attr('stroke-dasharray', '3,3');

    var lx = clamp(state.px, 70, 930);
    var ly = state.py - 104;
    if (ly < 26) ly = Math.min(state.py + 118, 318);
    var t1 = halo(label(gLabel, 'L(x=' + Math.round(state.px) + ', y=' + Math.round(GROUND_Y - state.py) +
      ', θ=' + deg(th).toFixed(0) + '°)', lx, ly, 9, 'middle', '#111'));
    var t2 = halo(label(gLabel, (T.i === 0 ? '= 0  · ' : '> 0  · ') + T.n, lx, ly + 11, 8, 'middle', T.i === 0 ? '#9aa2aa' : T.c));
    gLabel.line(lx, ly + (ly < state.py ? 3 : -8), state.px, state.py + (ly < state.py ? -14 : 14))
      .stroke({ color: '#b9bfc5', width: 0.6 }).attr('stroke-dasharray', '2,2').back();
    t1.front(); t2.front();
  }

  function update() { drawLive(); drawPanel(); drawProbe(); }

  // ---------- interaction ----------
  function clampPoint() {
    if (state.inside) {
      state.px = clamp(state.px, 68, 178);
      state.py = clamp(state.py, 149, 292);
    } else {
      state.px = clamp(state.px, 18, 975);
      state.py = clamp(state.py, 18, 322);
      if (state.px > 46 && state.px < 200 && state.py > 130 && state.py < 312) state.px = 206;
    }
  }
  function toSvg(evt) {
    var pt = draw.node.createSVGPoint();
    pt.x = evt.clientX; pt.y = evt.clientY;
    var p = pt.matrixTransform(draw.node.getScreenCTM().inverse());
    return { x: p.x, y: p.y };
  }
  var dragging = false;
  draw.node.addEventListener('mousedown', function (e) {
    var p = toSvg(e), dx = p.x - state.px, dy = p.y - state.py;
    if (dx * dx + dy * dy < 30 * 30) { dragging = true; e.preventDefault(); }
  });
  window.addEventListener('mouseup', function () { dragging = false; });
  draw.node.addEventListener('mousemove', function (e) {
    var p = toSvg(e);
    if (dragging) {
      state.px = p.x; state.py = p.y; clampPoint(); update();
    } else {
      var dx = p.x - state.px, dy = p.y - state.py;
      if (dx * dx + dy * dy > 100) { hoverTheta = Math.atan2(-dy, dx); drawProbe(); }
    }
  });

  window.toggle_locationView = function (on) {
    state.inside = on;
    if (on) { state.px = DOT_HI.x; state.py = DOT_HI.y; }
    else { state.px = FREE_A.x; state.py = FREE_A.y; }
    clampPoint(); update();
  };
  window.update_apertureSize = function (v) { state.aperture = v; update(); };

  // ---------- demo steps ----------
  var steps = [
    { t: 'A point in empty space',
      n: 'Drag the red marker anywhere in the open scene. Every direction around it carries some radiance — green toward the tree, bright toward the sky, near-black toward the ground — so the angular plot is fully populated.',
      s: { loc: 'free', ap: 3, pt: [380, 240] } },
    { t: 'Position changes the angular pattern',
      n: 'Move the point closer to the tree and the green wedge of directions grows while the sky wedge shrinks. The same function, evaluated at a different (x, y), gives a different distribution over θ.',
      s: { loc: 'free', ap: 3, pt: [600, 212] } },
    { t: 'Step inside the pinhole camera',
      n: 'Now sample a point on the camera\u2019s back wall. Almost every spoke goes to zero — only the narrow bundle of directions passing through the pinhole carries light, and it comes from the opposite side of the scene.',
      s: { loc: 'camera', ap: 3, pt: [DOT_HI.x, DOT_HI.y] } },
    { t: 'Widen the aperture',
      n: 'Enlarging the pinhole widens the non-zero cone at that same point: more directions light up, and each point now mixes radiance from a broader patch of the scene — the image blurs.',
      s: { loc: 'camera', ap: 18, pt: [DOT_HI.x, DOT_HI.y] } },
    { t: 'A camera is a sparse sample of the plenoptic function',
      n: 'Shrink the pinhole back down: the dense free-space fan collapses to a single admitted ray. A photograph is just a 2D slice of this much richer function — which is exactly what a NeRF tries to recover.',
      s: { loc: 'camera', ap: 0.5, pt: [DOT_HI.x, DOT_HI.y] } }
  ];
  var cur = 0;
  function applyStep(i) {
    cur = (i + steps.length) % steps.length;
    var st = steps[cur].s;
    state.inside = (st.loc === 'camera');
    state.aperture = st.ap;
    state.px = st.pt[0]; state.py = st.pt[1];
    document.getElementById('locationViewInput').checked = state.inside;
    document.getElementById('apertureSizeInput').value = st.ap;
    document.getElementById('apertureSizeVal').value = st.ap;
    document.getElementById('demoNarration').innerHTML =
      '<strong>' + steps[cur].t + '</strong><br>' + steps[cur].n;
    document.getElementById('stepLabel').textContent = (cur + 1) + ' / ' + steps.length;
    clampPoint(); update();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };
  window.resetFig = function () { applyStep(0); };

  drawScene();
  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
