<!-- @FIGURE_UI_BEGIN -->
<p id="demoNarration" style="margin:0;font-size:12px;line-height:1.5;max-width:100%"></p>
<span style="display:flex;gap:6px;align-items:center;font-size:12px">
  <button onclick="prevStep()">◀</button>
