</span>
<label><input id="locationViewInput" type="checkbox" onchange="toggle_locationView(this.checked)"> Sample inside pinhole camera</label>
<label><input id="colorRaysInput" type="checkbox" onchange="toggle_colorRays(this.checked)"> Colour-code rays by radiance</label>
<label>Pinhole diameter: <output id="apertureSizeVal">3</output>
  <input id="apertureSizeInput" type="range" min="0.5" max="30" step="0.5" value="3"
         oninput="document.getElementById('apertureSizeVal').value=this.value;update_apertureSize(+this.value)"></label>
<span id="lReadout" style="display:block;font:12px/1.6 ui-monospace,Consolas,monospace;color:#111;border-top:1px solid #e2e6ea;padding-top:6px"></span>
<span id="polarMount" style="display:block;margin-top:2px"></span>
<span style="font-size:11.5px;color:#555;line-height:1.45">Drag the red marker (pale ring) to move the sample point (x, y). Move the mouse anywhere in the scene to probe one direction θ.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var W = 1000, H = 347;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H).attr('preserveAspectRatio', 'xMidYMid meet');

  var gScene = draw.group(), gLive = draw.group(), gHi = draw.group(), gLabel = draw.group();

  // ---------- scene constants (matched to the source artwork) ----------
  var GROUND_Y = 336;
  var CAM = { x0: 60, x1: 185, y0: 141, y1: 300 };
  var APX = CAM.x1, APY = 220;
  var DOT_HI = { x: 71, y: 159 }, DOT_LO = { x: 71, y: 246 };
  var FREE_A = { x: 380, y: 241 }, FREE_B = { x: 466, y: 89 };

  var TYPES = {
    sky:    { c: '#9fb3c6', i: 0.90, n: 'sky (bright)' },
    tree:   { c: '#28c80f', i: 0.72, n: 'tree canopy (green)' },
    trunk:  { c: '#8a5a2e', i: 0.46, n: 'tree trunk (brown)' },
    ground: { c: '#222222', i: 0.18, n: 'ground (dark)' },
    bird:   { c: '#444444', i: 0.32, n: 'bird' },
    camera: { c: '#666666', i: 0.22, n: 'camera body' },
    zero:   { c: '#c3cad1', i: 0.0,  n: 'zero \u2014 blocked by the camera wall' }
  };

  var CANOPY = [[700,118,40],[716,86,36],[752,76,36],[796,78,36],[828,96,32],[836,124,30],
                [810,146,28],[772,152,26],[730,146,30],[690,130,32],[668,110,26],
                [756,110,52],[800,116,44],[716,116,40]];
  var TRUNK = [[716,150],[744,142],[762,132],[778,142],[784,168],[776,220],[780,270],
               [786,306],[790,332],[762,332],[758,322],[726,322],[722,332],[696,332],
               [694,300],[702,250],[708,200],[710,170]];

  var state = { inside: false, aperture: 3, px: FREE_A.x, py: FREE_A.y, color: false };
  var hoverTheta = 0.45;

  // ---------- helpers ----------
  function label(g, str, x, y, size, anchor, color, weight) {
    var t = g.text(str);
    t.font({ family: 'sans-serif', size: size, anchor: anchor || 'start', weight: weight || 'normal' });
    t.fill(color || '#000');
    t.attr('x', x).attr('y', y);
    var ts = t.node.querySelector('tspan');
    if (ts) { ts.setAttribute('x', x); ts.setAttribute('y', y); ts.setAttribute('dy', 0); }
    return t;
  }
  function halo(t, w) {
    t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': w || 4, 'stroke-linejoin': 'round' });
    return t;
  }
  function drawArrow(g, x1, y1, x2, y2, color, w, hs) {
    var ang = Math.atan2(y2 - y1, x2 - x1);
    var bx = x2 - Math.cos(ang) * hs, by = y2 - Math.sin(ang) * hs;
    g.line(x1, y1, bx, by).stroke({ color: color, width: w, linecap: 'round' });
    var nx = Math.cos(ang + Math.PI / 2) * hs * 0.34, ny = Math.sin(ang + Math.PI / 2) * hs * 0.34;
    g.polygon([[x2, y2], [bx + nx, by + ny], [bx - nx, by - ny]]).fill(color).stroke('none');
  }
  function hitLine(g, x1, y1, x2, y2, tip) {
    var h = g.line(x1, y1, x2, y2).stroke({ color: '#000', width: 8, opacity: 0 }).css('cursor', 'pointer');
    h.on('mousemove', function (e) { showTooltip(tip, e); });
    h.on('mouseleave', hideTooltip);
    return h;
  }
  function clamp(v, a, b) { return Math.min(b, Math.max(a, v)); }
  function deg(th) { var v = th * 180 / Math.PI; while (v < 0) v += 360; while (v >= 360) v -= 360; return v; }

  // ---------- geometry tests ----------
  function inCanopy(x, y) {
    if (x < 638 || x > 872 || y < 36 || y > 184) return false;
    for (var i = 0; i < CANOPY.length; i++) {
      var c = CANOPY[i], dx = x - c[0], dy = y - c[1];
      if (dx * dx + dy * dy <= c[2] * c[2]) return true;
    }
    return false;
  }
  function inTrunk(x, y) {
    if (x < 690 || x > 792 || y < 128 || y > 334) return false;
    var inside = false;
    for (var i = 0, j = TRUNK.length - 1; i < TRUNK.length; j = i++) {
      var xi = TRUNK[i][0], yi = TRUNK[i][1], xj = TRUNK[j][0], yj = TRUNK[j][1];
      if (((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi)) inside = !inside;
    }
    return inside;
  }
  function inBird(x, y) { var dx = x - 952, dy = y - 30; return dx * dx + dy * dy < 280; }
  function apGap() { return Math.max(0.6, state.aperture); }
  function inWall(x, y) {
    if (x < 55 || x > 190 || y < 136 || y > 305) return false;
    if (x >= 57 && x <= 63 && y >= 138 && y <= 303) return true;
    if (y >= 138 && y <= 144 && x >= 57 && x <= 188) return true;
    if (y >= 297 && y <= 303 && x >= 57 && x <= 188) return true;
    if (x >= 182 && x <= 188 && y >= 138 && y <= 303) {
      var a = apGap();
      if (y > APY - a / 2 && y < APY + a / 2) return false;
      return true;
    }
    return false;
  }

  // ---------- ray tracing of the plenoptic function ----------
  function trace(px, py, th, inside) {
    var dx = Math.cos(th), dy = -Math.sin(th), step = 2.4;
    for (var t = 3; t < 1500; t += step) {
      var x = px + dx * t, y = py + dy * t;
      if (inWall(x, y)) return inside ? 'zero' : 'camera';
      if (y >= GROUND_Y) return 'ground';
      if (inCanopy(x, y)) return 'tree';
      if (inTrunk(x, y)) return 'trunk';
      if (inBird(x, y)) return 'bird';
      if (x < -20 || x > W + 20 || y < -20) return 'sky';
    }
    return 'sky';
  }
  function directionList(px, py, inside, count) {
    var d = [], i;
    for (i = 0; i < count; i++) d.push(i * 2 * Math.PI / count);
    if (inside) {
      var a = apGap();
      for (i = 0; i <= 10; i++) {
        var ty = APY - a / 2 + a * i / 10;
        d.push(Math.atan2(-(ty - py), APX + 5 - px));
      }
    }
    d.sort(function (m, n) { return m - n; });
    return d;
  }

  // ---------- static scene (faithful to the source image) ----------
  function drawScene() {
    gScene.rect(W, 11).move(0, GROUND_Y).fill('#000');

    var canopy = gScene.group();
    CANOPY.forEach(function (c) { canopy.circle(c[2] * 2).center(c[0], c[1]).fill('#28c80f'); });
    var trunk = gScene.polygon(TRUNK).fill('#8a5a2e').stroke('none');
    [canopy, trunk].forEach(function (el) {
      el.css('cursor', 'pointer');
      el.on('mousemove', function (e) { showTooltip('Scene object: it sends radiance out in every direction', e); });
      el.on('mouseleave', hideTooltip);
      el.on('click', function () {
        showPopup('Scene radiance',
          'Every surface in the scene sends light out in many directions. The plenoptic function L(x, y, \u03b8) records, at each point of empty space, how much light arrives from each direction \u03b8 \u2014 green from the canopy, brown from the trunk, near-black from the ground, bright from the sky.');
      });
    });

    gScene.path('M944,52 L946,34 L934,24 L948,26 L952,10 L960,20 L972,16 L964,26 L974,30 L958,32 L952,46 Z')
      .fill('#fff').stroke({ color: '#000', width: 1.6, linejoin: 'round' });

    var s = { color: '#000', width: 2.4, linecap: 'square' };
    gScene.line(CAM.x0, CAM.y0, CAM.x0, CAM.y1).stroke(s);
    gScene.line(CAM.x0, CAM.y0, CAM.x1, CAM.y0).stroke(s);
    gScene.line(CAM.x0, CAM.y1, CAM.x1, CAM.y1).stroke(s);
    halo(label(gScene, 'Pinhole camera', 52, 128, 22, 'start', '#000'), 5);

    [DOT_HI, DOT_LO].forEach(function (d) { gScene.circle(15).center(d.x, d.y).fill('#ff0000'); });

    drawArrow(gScene, 262, 260, DOT_HI.x + 7, DOT_HI.y + 4, '#000', 1.3, 8);
    drawArrow(gScene, 262, 203, DOT_LO.x + 7, DOT_LO.y - 4, '#000', 1.3, 8);
    hitLine(gScene, 262, 260, DOT_HI.x, DOT_HI.y, 'Light from below the axis lands above it \u2014 the image is inverted');
    hitLine(gScene, 262, 203, DOT_LO.x, DOT_LO.y, 'Light from above the axis lands below it \u2014 the image is inverted');

    // second free-space starburst, exactly as in the source: 20 thin black arrows
    var sb = gScene.group();
    for (var i = 0; i < 20; i++) {
      var th = i * Math.PI / 10, ux = Math.cos(th), uy = -Math.sin(th);
      drawArrow(sb, FREE_B.x + ux * 90, FREE_B.y + uy * 90, FREE_B.x + ux * 17, FREE_B.y + uy * 17, '#000', 1.2, 7);
    }
    gScene.circle(15).center(FREE_B.x, FREE_B.y).fill('#ff0000').css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('A second free-space sample: rays arrive from all 360\u00b0', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('A point in free space',
          'At any point of empty space light arrives from every direction at once. The starburst of inward arrows samples L(x, y, \u03b8) at this (x, y): one intensity per direction \u03b8. No camera is involved \u2014 the function is simply there.');
      });
  }

  // ---------- dynamic scene layer ----------
  function drawLive() {
    gLive.clear();
    var s = { color: '#000', width: 2.4, linecap: 'square' };
    var g = Math.max(apGap(), 2.5);
    gLive.line(CAM.x1, CAM.y0, CAM.x1, APY - g / 2).stroke(s);
    gLive.line(CAM.x1, APY + g / 2, CAM.x1, CAM.y1).stroke(s);
    var ap = gLive.rect(6, Math.max(g, 2.5)).center(CAM.x1, APY).fill('#ffffff')
      .stroke({ color: '#d08a00', width: 0.9 }).css('cursor', 'pointer');
    ap.on('mousemove', function (e) { showTooltip('Pinhole: diameter ' + state.aperture.toFixed(1) + ' units', e); })
      .on('mouseleave', hideTooltip)
