// @FIGURE_CODE_BEGIN
(function () {
  var W = 1000, H = 347;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H).attr('preserveAspectRatio', 'xMidYMid meet');

  var gScene = draw.group(), gLive = draw.group(), gHi = draw.group(), gLabel = draw.group();

  // ---------- scene constants (matched to the source artwork) ----------
  var GROUND_Y = 336;
  var CAM = { x0: 60, x1: 185, y0: 141, y1: 300 };
  var APY = 220;
  var DOT_HI = { x: 71, y: 159 }, DOT_LO = { x: 71, y: 246 };
  var FREE_A = { x: 380, y: 241 }, FREE_B = { x: 466, y: 89 };

  var TYPES = {
    sky:    { c: '#9fb3c6', i: 0.90, n: 'sky (bright)' },
    tree:   { c: '#28c80f', i: 0.72, n: 'tree canopy (green)' },
    trunk:  { c: '#8a5a2e', i: 0.46, n: 'tree trunk (brown)' },
    ground: { c: '#222222', i: 0.18, n: 'ground (dark)' },
    bird:   { c: '#444444', i: 0.32, n: 'bird' },
    camera: { c: '#666666', i: 0.22, n: 'camera body' },
    zero:   { c: '#c3cad1', i: 0.0,  n: 'zero \u2014 blocked by the camera wall' }
  };

  var CANOPY = [[700,118,40],[716,86,36],[752,76,36],[796,78,36],[828,96,32],[836,124,30],
                [810,146,28],[772,152,26],[730,146,30],[690,130,32],[668,110,26],
                [756,110,52],[800,116,44],[716,116,40]];
  var TRUNK = [[716,150],[744,142],[762,132],[778,142],[784,168],[776,220],[780,270],
               [786,306],[790,332],[762,332],[758,322],[726,322],[722,332],[696,332],
               [694,300],[702,250],[708,200],[710,170]];

  var state = { inside: false, aperture: 3, px: FREE_A.x, py: FREE_A.y, color: false };
  var hoverTheta = 0.45;

  // ---------- helpers ----------
  function label(g, str, x, y, size, anchor, color, weight) {
    var t = g.text(str);
    t.font({ family: 'sans-serif', size: size, anchor: anchor || 'start', weight: weight || 'normal' });
    t.fill(color || '#000');
    t.attr('x', x).attr('y', y);
    var ts = t.node.querySelector('tspan');
    if (ts) { ts.setAttribute('x', x); ts.setAttribute('y', y); ts.setAttribute('dy', 0); }
    return t;
  }
  function halo(t, w) {
    t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': w || 4, 'stroke-linejoin': 'round' });
    return t;
  }
  function drawArrow(g, x1, y1, x2, y2, color, w, hs) {
    var ang = Math.atan2(y2 - y1, x2 - x1);
    var bx = x2 - Math.cos(ang) * hs, by = y2 - Math.sin(ang) * hs;
    g.line(x1, y1, bx, by).stroke({ color: color, width: w, linecap: 'round' });
    var nx = Math.cos(ang + Math.PI / 2) * hs * 0.34, ny = Math.sin(ang + Math.PI / 2) * hs * 0.34;
    g.polygon([[x2, y2], [bx + nx, by + ny], [bx - nx, by - ny]]).fill(color).stroke('none');
  }
  function hitLine(g, x1, y1, x2, y2, tip) {
    var h = g.line(x1, y1, x2, y2).stroke({ color: '#000', width: 8, opacity: 0 }).css('cursor', 'pointer');
    h.on('mousemove', function (e) { showTooltip(tip, e); });
    h.on('mouseleave', hideTooltip);
    return h;
  }
  function clamp(v, a, b) { return Math.min(b, Math.max(a, v)); }
  function deg(th) { var v = th * 180 / Math.PI; while (v < 0) v += 360; while (v >= 360) v -= 360; return v; }

  // ---------- geometry tests ----------
  function inCanopy(x, y) {
    if (x < 638 || x > 872 || y < 36 || y > 184) return false;
    for (var i = 0; i < CANOPY.length; i++) {
      var c = CANOPY[i], dx = x - c[0], dy = y - c[1];
      if (dx * dx + dy * dy <= c[2] * c[2]) return true;
    }
    return false;
  }
  function inTrunk(x, y) {
    if (x < 690 || x > 792 || y < 128 || y > 334) return false;
    var inside = false;
    for (var i = 0, j = TRUNK.length - 1; i < TRUNK.length; j = i++) {
      var xi = TRUNK[i][0], yi = TRUNK[i][1], xj = TRUNK[j][0], yj = TRUNK[j][1];
      if (((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi)) inside = !inside;
    }
    return inside;
  }
  function inBird(x, y) { var dx = x - 952, dy = y - 30; return dx * dx + dy * dy < 280; }
  function apGap() { return Math.max(0.6, state.aperture); }
  function inWall(x, y) {
    if (x < 55 || x > 190 || y < 136 || y > 305) return false;
    if (x >= 57 && x <= 63 && y >= 138 && y <= 303) return true;
    if (y >= 138 && y <= 144 && x >= 57 && x <= 188) return true;
    if (y >= 297 && y <= 303 && x >= 57 && x <= 188) return true;
    if (x >= 182 && x <= 188 && y >= 138 && y <= 303) {
      var a = apGap();
      if (y > APY - a / 2 && y < APY + a / 2) return false;
      return true;
    }
    return false;
  }

  // ---------- ray tracing of the plenoptic function ----------
  function trace(px, py, th, inside) {
    var dx = Math.cos(th), dy = -Math.sin(th), step = 2.4;
    for (var t = 3; t < 1500; t += step) {
      var x = px + dx * t, y = py + dy * t;
      if (inWall(x, y)) return inside ? 'zero' : 'camera';
      if (y >= GROUND_Y) return 'ground';
      if (inCanopy(x, y)) return 'tree';
      if (inTrunk(x, y)) return 'trunk';
      if (inBird(x, y)) return 'bird';
      if (x < -20 || x > W + 20 || y < -20) return 'sky';
    }
    return 'sky';
  }
  function directionList(px, py, inside, count) {
    var d = [], i;
    for (i = 0; i < count; i++) d.push(i * 2 * Math.PI / count);
    if (inside) {
      var a = apGap();
      for (i = 0; i <= 10; i++) {
        var ty = APY - a / 2 + a * i / 10;
        d.push(Math.atan2(-(ty - py), CAM.x1 + 5 - px));
      }
    }
    d.sort(function (m, n) { return m - n; });
    return d;
  }

  // ---------- static scene (faithful to the source artwork) ----------
  function drawScene() {
    gScene.rect(W, 11).move(0, GROUND_Y).fill('#000');

    var canopy = gScene.group();
    CANOPY.forEach(function (c) { canopy.circle(c[2] * 2).center(c[0], c[1]).fill('#28c80f'); });
    var trunk = gScene.polygon(TRUNK).fill('#8a5a2e').stroke('none');
    [canopy, trunk].forEach(function (el) {
      el.css('cursor', 'pointer');
      el.on('mousemove', function (e) { showTooltip('Scene object: it sends radiance out in every direction', e); });
      el.on('mouseleave', hideTooltip);
      el.on('click', function () {
        showPopup('Scene radiance',
          'Every surface in the scene sends light out in many directions. The plenoptic function L(x, y, \u03b8) records, at each point of empty space, how much light arrives from each direction \u03b8 \u2014 green from the canopy, brown from the trunk, near-black from the ground, bright from the sky.');
      });
    });

    gScene.path('M944,52 L946,34 L934,24 L948,26 L952,10 L960,20 L972,16 L964,26 L974,30 L958,32 L952,46 Z')
      .fill('#fff').stroke({ color: '#000', width: 1.6, linejoin: 'round' });

    var s = { color: '#000', width: 2.4, linecap: 'square' };
    gScene.line(CAM.x0, CAM.y0, CAM.x0, CAM.y1).stroke(s);
    gScene.line(CAM.x0, CAM.y0, CAM.x1, CAM.y0).stroke(s);
    gScene.line(CAM.x0, CAM.y1, CAM.x1, CAM.y1).stroke(s);
    halo(label(gScene, 'Pinhole camera', 52, 128, 28, 'start', '#000'), 6);

    [DOT_HI, DOT_LO].forEach(function (d) { gScene.circle(15).center(d.x, d.y).fill('#ff0000'); });

    // long crossing rays through the aperture (image inversion), tails far to the right
    drawArrow(gScene, 280, 269, DOT_HI.x + 7, DOT_HI.y + 4, '#000', 1.3, 8);
    drawArrow(gScene, 280, 199, DOT_LO.x + 7, DOT_LO.y - 4, '#000', 1.3, 8);
    hitLine(gScene, 280, 269, DOT_HI.x, DOT_HI.y, 'Light from below the axis lands above it \u2014 the image is inverted');
    hitLine(gScene, 280, 199, DOT_LO.x, DOT_LO.y, 'Light from above the axis lands below it \u2014 the image is inverted');

    // second free-space starburst: 20 thin black inward arrows
    var sb = gScene.group();
    for (var i = 0; i < 20; i++) {
      var th = i * Math.PI / 10, ux = Math.cos(th), uy = -Math.sin(th);
      drawArrow(sb, FREE_B.x + ux * 90, FREE_B.y + uy * 90, FREE_B.x + ux * 17, FREE_B.y + uy * 17, '#000', 1.2, 7);
    }
    gScene.circle(15).center(FREE_B.x, FREE_B.y).fill('#ff0000').css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('A second free-space sample: rays arrive from all 360\u00b0', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('A point in free space',
          'At any point of empty space light arrives from every direction at once. The starburst of inward arrows samples L(x, y, \u03b8) at this (x, y): one intensity per direction \u03b8. No camera is involved \u2014 the function is simply there.');
      });
  }

  // ---------- dynamic scene layer ----------
  function drawLive() {
    gLive.clear();
    var s = { color: '#000', width: 2.4, linecap: 'square' };
    var g = Math.max(apGap(), 2.5);
    gLive.line(CAM.x1, CAM.y0, CAM.x1, APY - g / 2).stroke(s);
    gLive.line(CAM.x1, APY + g / 2, CAM.x1, CAM.y1).stroke(s);
    var ap = gLive.rect(6, Math.max(g, 2.5)).center(CAM.x1, APY).fill('#ffffff')
      .stroke({ color: '#d08a00', width: 0.9 }).css('cursor', 'pointer');
    ap.on('mousemove', function (e) { showTooltip('Pinhole: diameter ' + state.aperture.toFixed(1) + ' units', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The aperture does the blocking',
          'The pinhole is the only opening. It admits a narrow cone of directions at each interior point, so L(x, y, \u03b8) inside the camera is zero for almost every \u03b8. Widening it admits more directions \u2014 and blurs the image.');
      });

    var dirs = directionList(state.px, state.py, state.inside, 20);
    for (var i = 0; i < dirs.length; i++) {
      var th = dirs[i], ux = Math.cos(th), uy = -Math.sin(th);
      var ty = trace(state.px, state.py, th, state.inside), T = TYPES[ty];
      if (ty === 'zero') {
        gLive.line(state.px + ux * 30, state.py + uy * 30, state.px + ux * 48, state.py + uy * 48)
          .stroke({ color: T.c, width: 1, linecap: 'round' }).attr('stroke-dasharray', '2,2.5');
      } else {
        drawArrow(gLive, state.px + ux * 90, state.py + uy * 90, state.px + ux * 17, state.py + uy * 17,
          state.color ? T.c : '#000', 1.2, 7);
        hitLine(gLive, state.px + ux * 90, state.py + uy * 90, state.px + ux * 20, state.py + uy * 20,
          '\u03b8 = ' + deg(th).toFixed(0) + '\u00b0  \u2192  ' + T.n);
      }
    }

    gLive.circle(27).center(state.px, state.py).fill('none').stroke({ color: '#ffb3b3', width: 2.2 });
    var m = gLive.circle(15).center(state.px, state.py).fill('#ff0000').css('cursor', 'grab');
    m.on('mousemove', function (e) { showTooltip('Drag me \u2014 the sample point (x, y) of L(x, y, \u03b8)', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The active sample point',
          'This marker is the (x, y) at which the plenoptic function is evaluated. The polar readout in the panel shows L as a function of direction \u03b8 around it. Drag it into the camera, or out into the open scene, and watch the angular distribution change.');
      });

    if (state.inside) {
      gLive.line(232, 288, 196, 296).stroke({ color: '#999', width: 0.9 }).attr('stroke-dasharray', '3,2.5');
      halo(label(gLive, 'most directions are zero', 344, 286, 20, 'middle', '#333'), 5);
      halo(label(gLive, 'inside the camera', 344, 310, 20, 'middle', '#333'), 5);
    }
  }

  // ---------- collision-tested placement for the live L(...) annotation ----------
  function staticBoxes() {
    return [
      { x: 38, y: 98, w: 260, h: 220 },                 // camera, its label and the crossing rays
      { x: 366, y: -12, w: 200, h: 202 },               // free-space starburst B
      { x: 646, y: 26, w: 250, h: 314 },                // tree
      { x: 916, y: 0, w: 76, h: 66 },                   // bird
      { x: -10, y: 326, w: 1020, h: 34 },               // ground bar
      { x: state.px - 102, y: state.py - 102, w: 204, h: 204 } // the live ray fan
    ];
  }
  function hits(b, list) {
    for (var i = 0; i < list.length; i++) {
      var o = list[i];
      if (b.x < o.x + o.w && b.x + b.w > o.x && b.y < o.y + o.h && b.y + b.h > o.y) return true;
    }
    return false;
  }
  var CANDS = [
    [0, -124, 'middle'], [0, 124, 'middle'], [0, -124, 'start'], [0, -124, 'end'],
    [120, -80, 'start'], [-120, -80, 'end'], [120, 80, 'start'], [-120, 80, 'end'],
    [136, 6, 'start'], [-136, 6, 'end']
  ];
  function placeLabel(txt, size) {
    var w = txt.length * size * 0.52, h = size * 1.15, boxes = staticBoxes();
    for (var i = 0; i < CANDS.length; i++) {
      var c = CANDS[i], cx = state.px + c[0], cy = state.py + c[1], a = c[2];
      var bx = (a === 'middle') ? cx - w / 2 : (a === 'start' ? cx - 4 : cx - w + 4);
      var b = { x: bx, y: cy - h * 0.82, w: w, h: h * 1.1 };
      if (b.x < 8 || b.x + b.w > W - 8 || b.y < 12 || b.y + b.h > 322) continue;
      if (hits(b, boxes)) continue;
      return { x: cx, y: cy, anchor: a, box: b, near: true };
    }
    // fixed caption slot in the empty upper-left band \u2014 always clear
    var fb = { x: 70, y: 34, anchor: 'start' };
    fb.box = { x: 66, y: 34 - h * 0.82, w: w, h: h * 1.1 };
    fb.near = false;
    return fb;
  }

  // ---------- in-scene live L(x, y, θ) annotation + probe ray ----------
  function drawProbe() {
    gHi.clear(); gLabel.clear();
    var th = hoverTheta, ux = Math.cos(th), uy = -Math.sin(th);
    var ty = trace(state.px, state.py, th, state.inside), T = TYPES[ty];

    gHi.line(state.px + ux * 12, state.py + uy * 12, state.px + ux * 98, state.py + uy * 98)
      .stroke({ color: '#e02020', width: 1.3, opacity: 0.9 }).attr('stroke-dasharray', '4,3');

    var txt = 'L(' + Math.round(state.px) + ', ' + Math.round(GROUND_Y - state.py) + ', ' +
      deg(th).toFixed(0) + '\u00b0) = ' + (T.i === 0 ? '0' : T.i.toFixed(2));
    var SZ = 22;
    var p = placeLabel(txt, SZ);

    if (p.near) {
      var ax = (p.anchor === 'middle') ? p.x : (p.anchor === 'start' ? p.x : p.x);
      gLabel.line(ax, p.y + (p.y < state.py ? 6 : -15), state.px, state.py + (p.y < state.py ? -18 : 18))
        .stroke({ color: '#c4cad0', width: 0.9 }).attr('stroke-dasharray', '2,2');
    }
    gLabel.rect(p.box.w + 10, p.box.h + 4).move(p.box.x - 5, p.box.y - 2)
      .fill('#ffffff').opacity(0.8).radius(3);
    halo(label(gLabel, txt, p.x, p.y, SZ, p.anchor, T.i === 0 ? '#7b828a' : '#111'), 5);

    updateReadout(th, T);
    drawPanelProbe(th);
  }

  // ---------- compact side-panel polar readout ----------
  var PW = 250, PH = 164, PCX = 125, PCY = 80, PR = 60;
  var pdraw = SVG().addTo(document.getElementById('polarMount')).size(PW, PH);
  pdraw.viewbox(0, 0, PW, PH).attr('style', 'max-width:100%;height:auto;display:block');
  var pBase = pdraw.group(), pProbe = pdraw.group();
  pdraw.node.style.cursor = 'pointer';
  pdraw.on('mousemove', function (e) {
    showTooltip('Polar plot of L(\u03b8) at the active point: spoke length = radiance, colour = what that direction sees', e);
  });
  pdraw.on('mouseleave', hideTooltip);
  pdraw.on('click', function () {
    showPopup('Reading the polar plot',
      'Each spoke is one direction \u03b8 leaving the sample point; its length is the radiance L(x, y, \u03b8) arriving from that direction. In free space the disc is full. Inside the pinhole camera nearly every spoke collapses to a faint dashed stub \u2014 the function is almost everywhere zero.');
  });

  function drawPanel() {
    pBase.clear();
    pBase.rect(PW - 2, PH - 2).move(1, 1).fill('#ffffff').stroke({ color: '#dde2e7', width: 1 }).radius(6);
    pBase.circle(PR * 2).center(PCX, PCY).fill('none').stroke({ color: '#e2e6ea', width: 1 }).attr('stroke-dasharray', '2,3');
    pBase.circle(PR).center(PCX, PCY).fill('none').stroke({ color: '#eef1f4', width: 1 });

    var dirs = directionList(state.px, state.py, state.inside, 96);
    var solids = [];
    for (var i = 0; i < dirs.length; i++) {
      var th = dirs[i], ux = Math.cos(th), uy = -Math.sin(th);
      var ty = trace(state.px, state.py, th, state.inside), T = TYPES[ty];
      if (ty === 'zero') {
        pBase.line(PCX + ux * 7, PCY + uy * 7, PCX + ux * 21, PCY + uy * 21)
          .stroke({ color: T.c, width: 0.9 }).attr('stroke-dasharray', '2,2.5');
      } else solids.push([ux, uy, T]);
    }
    solids.forEach(function (sp) {
      var L = 7 + (PR - 7) * sp[2].i;
      pBase.line(PCX + sp[0] * 7, PCY + sp[1] * 7, PCX + sp[0] * L, PCY + sp[1] * L)
        .stroke({ color: sp[2].c, width: 1.7, linecap: 'round' });
    });
    pBase.circle(6).center(PCX, PCY).fill('#ff0000');

    label(pBase, '0\u00b0', PCX + PR + 7, PCY + 4, 10, 'start', '#8a9099');
    label(pBase, '90\u00b0', PCX, PCY - PR - 6, 10, 'middle', '#8a9099');
    label(pBase, '180\u00b0', PCX - PR - 7, PCY + 4, 10, 'end', '#8a9099');
    label(pBase, '270\u00b0', PCX, PCY + PR + 15, 10, 'middle', '#8a9099');

    var cap = document.getElementById('panelState');
    if (cap) cap.textContent = state.inside ? 'point inside the pinhole camera' : 'point in free space';
  }

  function drawPanelProbe(th) {
    pProbe.clear();
    var ux = Math.cos(th), uy = -Math.sin(th);
    pProbe.line(PCX + ux * 6, PCY + uy * 6, PCX + ux * (PR + 6), PCY + uy * (PR + 6))
      .stroke({ color: '#e02020', width: 1.3 }).attr('stroke-dasharray', '4,3');
    pProbe.circle(5).center(PCX + ux * (PR + 6), PCY + uy * (PR + 6)).fill('#e02020');
  }

  function updateReadout(th, T) {
    var el = document.getElementById('lReadout');
    if (!el) return;
    el.innerHTML =
      'x = ' + Math.round(state.px) + '&nbsp; y = ' + Math.round(GROUND_Y - state.py) +
      '&nbsp; \u03b8 = ' + deg(th).toFixed(0) + '\u00b0<br>' +
      'L(x, y, \u03b8) = <strong style="color:' + (T.i === 0 ? '#8a9099' : T.c) + '">' +
      (T.i === 0 ? '0' : T.i.toFixed(2)) + '</strong><br>' +
      '<span style="font-family:sans-serif;font-size:11px;color:#555">this direction sees: ' + T.n + '</span>';
  }

  function update() { drawLive(); drawPanel(); drawProbe(); }

  // ---------- interaction ----------
  function clampPoint() {
    if (state.inside) {
      state.px = clamp(state.px, 68, 176);
      state.py = clamp(state.py, 150, 291);
    } else {
      state.px = clamp(state.px, 20, 970);
      state.py = clamp(state.py, 20, 322);
      if (state.px > 46 && state.px < 200 && state.py > 130 && state.py < 312) state.px = 210;
    }
  }
  function toSvg(evt) {
    var pt = draw.node.createSVGPoint();
    pt.x = evt.clientX; pt.y = evt.clientY;
    var p = pt.matrixTransform(draw.node.getScreenCTM().inverse());
    return { x: p.x, y: p.y };
  }
  var dragging = false;
  draw.node.addEventListener('mousedown', function (e) {
    var p = toSvg(e), dx = p.x - state.px, dy = p.y - state.py;
    if (dx * dx + dy * dy < 32 * 32) { dragging = true; e.preventDefault(); }
  });
  window.addEventListener('mouseup', function () { dragging = false; });
  draw.node.addEventListener('mousemove', function (e) {
    var p = toSvg(e);
    if (dragging) { state.px = p.x; state.py = p.y; clampPoint(); update(); }
    else {
      var dx = p.x - state.px, dy = p.y - state.py;
      if (dx * dx + dy * dy > 120) { hoverTheta = Math.atan2(-dy, dx); drawProbe(); }
    }
  });

  window.toggle_locationView = function (on) {
    state.inside = on;
    if (on) { state.px = DOT_HI.x; state.py = DOT_HI.y; }
    else { state.px = FREE_A.x; state.py = FREE_A.y; }
    clampPoint(); update();
  };
  window.toggle_colorRays = function (on) { state.color = on; update(); };
  window.update_apertureSize = function (v) { state.aperture = v; update(); };

  // ---------- demo steps ----------
  var steps = [
    { t: 'A point in empty space',
      n: 'Every direction around the red marker carries some radiance \u2014 toward the tree, the sky, the ground \u2014 so the polar plot below is fully populated. Drag the marker anywhere in the open scene.',
      s: { loc: 'free', ap: 3, col: false, pt: [FREE_A.x, FREE_A.y] } },
    { t: 'Position changes the angular pattern',
      n: 'Colour-coding is on. Closer to the tree the green wedge of directions grows while the sky wedge shrinks: the same function at a different (x, y) gives a different distribution over \u03b8.',
      s: { loc: 'free', ap: 3, col: true, pt: [600, 210] } },
    { t: 'Step inside the pinhole camera',
      n: 'Now sample a point on the camera\u2019s back wall. Almost every spoke collapses to a faint dashed stub \u2014 only the narrow bundle passing through the pinhole carries light, and it comes from the opposite side of the scene.',
      s: { loc: 'camera', ap: 3, col: true, pt: [DOT_HI.x, DOT_HI.y] } },
    { t: 'Widen the aperture',
      n: 'Enlarging the pinhole widens the non-zero cone at that same point: more directions light up, and each image point now mixes radiance from a broader patch of the scene \u2014 the image blurs.',
      s: { loc: 'camera', ap: 18, col: true, pt: [DOT_HI.x, DOT_HI.y] } },
    { t: 'A camera is a sparse sample of L',
      n: 'Shrink the pinhole back down: the dense free-space fan collapses to a single admitted ray. A photograph is just a thin slice of this much richer function \u2014 recovering the rest is exactly the view-synthesis problem.',
      s: { loc: 'camera', ap: 0.5, col: true, pt: [DOT_HI.x, DOT_HI.y] } }
  ];
  var cur = 0;
  function applyStep(i) {
    cur = (i + steps.length) % steps.length;
    var st = steps[cur].s;
    state.inside = (st.loc === 'camera');
    state.aperture = st.ap;
    state.color = st.col;
    state.px = st.pt[0]; state.py = st.pt[1];
    hoverTheta = state.inside ? 0.05 : 0.45;
    document.getElementById('locationViewInput').checked = state.inside;
    document.getElementById('colorRaysInput').checked = state.color;
    document.getElementById('apertureSizeInput').value = st.ap;
    document.getElementById('apertureSizeVal').value = st.ap;
    document.getElementById('demoNarration').innerHTML =
      '<strong>' + steps[cur].t + '</strong><br>' + steps[cur].n;
    document.getElementById('stepLabel').textContent = (cur + 1) + ' / ' + steps.length;
    clampPoint(); update();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };
  window.resetFig = function () { applyStep(0); };

  drawScene();
  applyStep(0);
  window.__markRendered();
})();
